/**
 * Block of code, such as an install command or config sample (`design/components/code-block.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/code-block.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  cell,
  elementRef,
  measured,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/code-block.module.css'
import { Button, type ButtonProps } from '../controls/Button'

/** Block of code, such as an install command or config sample: the inputs it takes, by the React member's prop names. */
export interface CodeBlockProps {
  /**
   * Draws the copy control, the block's only control.
   */
  copyable?: boolean
  /**
   * The copy control's accessible name, default `'Copy'`; apps pass a localized one.
   */
  copyLabel?: string
  /**
   * The accessible name when the block overflows and becomes a scroll region; defaults to `'Code
   * block'`, and apps pass a localized one.
   */
  label?: string
}

/** Block of code, such as an install command or config sample. */
@Component({
  selector: 'pm-code-block',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, SlotOutlet, SlotTemplate, Button],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
@if (e1()) {<div
[attr.class]="e2()"
[attr.data-state]="e3()"
><pre
[attr.class]="e4()"
[attr.data-overflowing]="e5()"
[attr.data-copyable]="e6()"
[attr.tabindex]="e7()"
[attr.role]="e8()"
[attr.aria-label]="e9()"
data-member="code-block"
[pmRef]="block"
><code><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></code></pre>
<div
[attr.class]="e10()"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e11()"
[icon]="e12()"
[label]="e13()"
(click)="h1()"
></pm-button></div>
<span
[attr.class]="e14()"
aria-live="polite"
>{{ e15() }}</span></div>} @else {<pre
[attr.class]="e16()"
[attr.data-overflowing]="e17()"
[attr.data-copyable]="e18()"
[attr.tabindex]="e19()"
[attr.role]="e20()"
[attr.aria-label]="e21()"
data-member="code-block"
[pmRef]="block"
><code><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></code></pre>}`,
})
export class CodeBlock {
  /**
   * Draws the copy control, the block's only control.
   */
  readonly copyable = input<
    Exclude<CodeBlockProps['copyable'], undefined>,
    CodeBlockProps['copyable']
  >(false, {
    transform: (value: CodeBlockProps['copyable']) => (value === undefined ? false : value),
  })
  /**
   * The copy control's accessible name, default `'Copy'`; apps pass a localized one.
   */
  readonly copyLabel = input<
    Exclude<CodeBlockProps['copyLabel'], undefined>,
    CodeBlockProps['copyLabel']
  >('Copy', {
    transform: (value: CodeBlockProps['copyLabel']) => (value === undefined ? 'Copy' : value),
  })
  /**
   * The accessible name when the block overflows and becomes a scroll region; defaults to `'Code
   * block'`, and apps pass a localized one.
   */
  readonly label = input<Exclude<CodeBlockProps['label'], undefined>, CodeBlockProps['label']>(
    'Code block',
    { transform: (value: CodeBlockProps['label']) => (value === undefined ? 'Code block' : value) },
  )
  protected readonly $ = useMember({
    events: [],
    props: {
      copyable: () => this.copyable(),
      copyLabel: () => this.copyLabel(),
      label: () => this.label(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly overflowing = cell(() => false)
  protected readonly copied = cell(() => false)
  protected readonly copies = cell(() => 0)
  protected readonly block = elementRef<HTMLElement>()
  protected readonly copy = measured(
    () => () =>
      void navigator.clipboard.writeText(this.$.text('default')).then(
        () => {
          this.copied.value = true
          this.copies.value += 1
        },
        () => undefined,
      ),
  )
  private release1: (() => void) | undefined
  private release2: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    watchEffect(
      () => this.$p.copyable,
      () => this.effect1(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    watchEffect(
      () => this.copies.value,
      () => this.effect2(),
      false,
    )
  }

  protected e1() {
    return this.$p.copyable
  }

  protected e2() {
    if (!this.$p.copyable) return undefined as never
    return styles.copyable
  }

  protected e3() {
    if (!this.$p.copyable) return undefined as never
    return this.copied.value ? 'copied' : undefined
  }

  protected e4() {
    if (!this.$p.copyable) return undefined as never
    return styles.block
  }

  protected e5() {
    if (!this.$p.copyable) return undefined as never
    return this.overflowing.value ? '' : undefined
  }

  protected e6() {
    if (!this.$p.copyable) return undefined as never
    return this.$p.copyable ? '' : undefined
  }

  protected e7() {
    if (!this.$p.copyable) return undefined as never
    return this.overflowing.value ? 0 : undefined
  }

  protected e8() {
    if (!this.$p.copyable) return undefined as never
    return this.overflowing.value ? 'region' : undefined
  }

  protected e9() {
    if (!this.$p.copyable) return undefined as never
    return this.overflowing.value ? this.$p.label : undefined
  }

  protected e10() {
    if (!this.$p.copyable) return undefined as never
    return styles.control
  }

  protected e11(): ButtonProps['iconOnly'] {
    if (!this.$p.copyable) return undefined as never
    return true
  }

  protected e12(): ButtonProps['icon'] {
    if (!this.$p.copyable) return undefined as never
    return this.copied.value ? 'confirm' : 'copy'
  }

  protected e13(): ButtonProps['label'] {
    if (!this.$p.copyable) return undefined as never
    return this.$p.copyLabel
  }

  protected h1(): void {
    if (!this.$p.copyable) return
    this.copy.value()
  }

  protected e14() {
    if (!this.$p.copyable) return undefined as never
    return styles.reader
  }

  protected e15() {
    if (!this.$p.copyable) return undefined as never
    return this.copied.value ? 'Copied' : ''
  }

  protected e16() {
    if (this.$p.copyable) return undefined as never
    return styles.block
  }

  protected e17() {
    if (this.$p.copyable) return undefined as never
    return this.overflowing.value ? '' : undefined
  }

  protected e18() {
    if (this.$p.copyable) return undefined as never
    return this.$p.copyable ? '' : undefined
  }

  protected e19() {
    if (this.$p.copyable) return undefined as never
    return this.overflowing.value ? 0 : undefined
  }

  protected e20() {
    if (this.$p.copyable) return undefined as never
    return this.overflowing.value ? 'region' : undefined
  }

  protected e21() {
    if (this.$p.copyable) return undefined as never
    return this.overflowing.value ? this.$p.label : undefined
  }

  private effect1(): void {
    this.release1?.()
    const run = () => {
      this.overflowing.value =
        this.block.value !== null && this.block.value.scrollWidth > this.block.value.clientWidth
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.block.value]) if (element) resize?.observe(element)
    const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
    for (const element of [this.block.value])
      if (element)
        mutation?.observe(element, { childList: true, characterData: true, subtree: true })
    this.release1 = () => {
      resize?.disconnect()
      mutation?.disconnect()
    }
    run()
  }

  private effect2(): void {
    this.release2?.()
    const timer = setTimeout(() => {
      this.copied.value = false
    }, 2000)
    this.release2 = () => clearTimeout(timer)
  }
}
